python3 << 'PYSCRIPT'
import yaml

with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_7/projects/gen-depth-contamination/registry.yaml') as f:
    data = yaml.safe_load(f)

print("===== COMPLETE JSD DECAY DATA FOR ALL EXPERIMENTS =====\n")

# Separate by domain
c4_exps = {}
arxiv_exps = {}
code_exps = {}
wiki_exps = {}
other_exps = {}

for exp_id, exp_info in data.get('experiments', {}).items():
    if not exp_info or not isinstance(exp_info, dict):
        continue

    metrics = exp_info.get('metrics', {})
    if 'pairwise_jsd' not in metrics:
        continue

    hyp = exp_info.get('hypothesis', '').lower()

    if 'c4' in exp_id.lower() or 'c4' in hyp:
        c4_exps[exp_id] = exp_info
    elif 'arxiv' in exp_id.lower() or 'arxiv' in hyp:
        arxiv_exps[exp_id] = exp_info
    elif 'code' in exp_id.lower() or 'code' in hyp:
        code_exps[exp_id] = exp_info
    elif 'wiki' in exp_id.lower() or 'wikipedia' in hyp or 'wiki' in hyp:
        wiki_exps[exp_id] = exp_info
    else:
        other_exps[exp_id] = exp_info

def print_experiments(title, exps):
    if not exps:
        return
    print(f"\n{title}")
    print("=" * 150)

    for exp_id in sorted(exps.keys()):
        exp = exps[exp_id]
        metrics = exp['metrics']
        jsd = metrics.get('pairwise_jsd', {})
        k = metrics.get('k_star', 'N/A')

        # Extract model info from hypothesis
        hyp = exp.get('hypothesis', '')[:100]

        print(f"\n{exp_id}:")
        print(f"  K*: {k}")
        print(f"  Hypothesis: {hyp}")
        print(f"  JSD: ", end="")
        jsd_pairs = []
        for pair in ['0v1', '1v2', '2v3', '3v4', '4v5', '5v6', '6v7']:
            if pair in jsd:
                jsd_pairs.append(f"{pair}={jsd[pair]:.6f}")
        print(" | ".join(jsd_pairs))

print_experiments("C4 DOMAIN EXPERIMENTS", c4_exps)
print_experiments("ARXIV DOMAIN EXPERIMENTS", arxiv_exps)
print_experiments("CODE DOMAIN EXPERIMENTS", code_exps)
print_experiments("WIKI DOMAIN EXPERIMENTS", wiki_exps)
print_experiments("OTHER/MVP EXPERIMENTS", other_exps)
